#!/usr/bin/env python3
"""Read-only evidence extraction. All outputs stay beside this file."""
from pathlib import Path
import hashlib,json,re
OUT=Path(__file__).resolve().parent
ROOT=OUT.parents[1]
SRC=ROOT/'decompiled/Assembly-CSharp'
def extract(file,signature):
    s=(SRC/file).read_text(encoding='utf-8-sig'); pos=s.index(signature); start=s.index('{',pos); depth=1; i=start+1
    # These selected methods contain no brace literals/comments; fail checks below.
    while depth:
        depth+=(s[i]=='{')-(s[i]=='}'); i+=1
    return s[pos:i],s[:pos].count('\n')+1

def main():
    entries=[]
    for f in sorted(SRC.glob('*.cs')):
        for n,line in enumerate(f.read_text(encoding='utf-8-sig').split('\n'),1):
            hits=re.findall(r'\b(GHexes|GWater)\.(\w+)',line)
            if hits:
                entries.append({'file':f.name,'line':n,'references':list(dict.fromkeys('.'.join(t) for t in hits)), 'code':line.strip()})
    (OUT/'shared-access-evidence.json').write_text(json.dumps(entries,ensure_ascii=False,indent=2)+'\n')
    blocksall=[]
    for name in ['baseline-Player-2026-11-05.log','run1-Player.log']:
        lines=(ROOT/'work'/name).read_text().split('\n'); starts=[i for i,l in enumerate(lines) if '* FPS infos' in l]; blocks=[]
        for n,end in zip(starts,starts[1:]+[len(lines)]):
            chunk=lines[n:end]; b={'file':name,'line':n+1,'frame':lines[n],'labels':{},'diagnostics':[]}
            for line in chunk:
                m=re.match(r'\s*([\d.]+) ms - (.*)',line)
                if m:b['labels'][m[2]]=float(m[1])
                if 'GC Memory=' in line:b['counts']=line
                if 'PlanBPerf] win=' in line:b['diagnostics'].append(line)
            blocks.append(b)
        (OUT/(name+'.blocks.json')).write_text(json.dumps(blocks,indent=2)+'\n'); blocksall+=blocks
    selected=[b for b in blocksall if b['line'] in ([6675,3634,7240] if b['file'].startswith('baseline') else [1047])]
    # x1 candidate is chosen by source author context, not asserted from profiler values.
    (OUT/'selected-profile-blocks.json').write_text(json.dumps(selected,indent=2)+'\n')
    manifest={str(f.relative_to(ROOT)):hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted(SRC.glob('*.cs'))}
    (OUT/'source-sha256.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print(f'{len(manifest)} source files; {len(entries)} direct shared-access lines; {len(blocksall)} FPS blocks. This is a lexical index, NOT a complete call graph.')
if __name__=='__main__':main()
