using System.Collections.Generic;
using System.Runtime.CompilerServices;
using UnityEngine;
namespace PlanBPerf.V2
{
    public static class ExactPrimitives
    {
        // Replace GHexes.GetWaterProximity(int2). Reverses bits 12..15 into weights 8,4,2,1.
        // Enum HasFlag in the game is a custom bitwise helper: there was NO Enum.HasFlag boxing.
        public static int WaterProximity(int2 coords)
        {
            uint f = (uint)GHexes.flags[coords.x, coords.y];
            return (int)(((f >> 9) & 8u) | ((f >> 11) & 4u) | ((f >> 13) & 2u) | ((f >> 15) & 1u));
        }
        // Replace only the Shuffle<int2> call in SItems.Update01s_DynamicItems.
        // Keep n RNG calls INCLUDING i=n-1; no Fisher-Yates variant, no CollectionsMarshal (not Mono API).
        public static void DynamicShuffle(IList<int2> source)
        {
            var list = source as List<int2>;
            if (list == null) { SMisc.Shuffle(source); return; }
            for (int i = 0; i < list.Count; i++)
            {
                int2 value = list[i];
                int index = UnityEngine.Random.Range(i, list.Count);
                list[i] = list[index];
                list[index] = value;
            }
        }
    }
    // Source audit: game creates textures but never resizes/reinitializes TextureInfos.tx.
    // Retains ACTUAL width (normal-map clone may differ from size). Reference replacement handled.
    // Third-party resize in-place requires Forget(info) BEFORE next access; otherwise disable this key.
    public static class TextureIndex<T> where T : struct
    {
        private sealed class Entry { public Texture2D Texture; public int Width; }
        private static readonly ConditionalWeakTable<SViewWorld.TextureInfos<T>, Entry> Entries = new ConditionalWeakTable<SViewWorld.TextureInfos<T>, Entry>();
        private static Entry Make(SViewWorld.TextureInfos<T> info) { return new Entry { Texture = info.tx, Width = info.tx.width }; }
        public static void Forget(SViewWorld.TextureInfos<T> info) { Entries.Remove(info); }
        public static int Run(SViewWorld.TextureInfos<T> info, int x, int y)
        {
            var e = Entries.GetValue(info, Make);
            if (!object.ReferenceEquals(e.Texture, info.tx)) { e.Texture = info.tx; e.Width = info.tx.width; }
            return y * e.Width + (x + info.size) % info.size;
        }
    }
}
